using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class VerifyC01Routes {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/검수/2026-11-07_C01_InstrumentDetail/";
 static Transform root;static JToken floor;
 static void Init(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;floor=JObject.Parse(File.ReadAllText(R+"/Docs/도면/Decision/원형공동/facility_layout.json"))["floors"].Single(f=>(string)f["id"]=="B5");Directory.CreateDirectory(O);}
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 static Vector3 V(JToken p)=>new Vector3((float)p[0],-82,-(float)p[1]);
 public static object Audit(){Init();Physics.SyncTransforms();var blocked=new List<object>();var groundMissing=new List<object>();var checks=new List<object>();int samples=0;
  foreach(var t in floor["tunnels"]){var p=V(t["p"]);var q=V(t["q"]);var d=(q-p).normalized;var right=Vector3.Cross(Vector3.up,d);p-=d*1.6f;q+=d*1.6f;int n=Mathf.CeilToInt(Vector3.Distance(p,q)/.45f);int failures=0;
   foreach(float lane in new[]{-.65f,0,.65f})for(int i=0;i<=n;i++){var pos=Vector3.Lerp(p,q,(float)i/n)+right*lane;samples++;var hits=Physics.OverlapCapsule(pos+Vector3.up*.36f,pos+Vector3.up*1.52f,.28f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).ToArray();if(hits.Length>0){failures++;blocked.Add(new{tunnel=(string)t["id"],i,lane,pos=pos.ToString(),hits=hits.Select(h=>PathOf(h.transform)).Distinct().ToArray()});}
    var down=Physics.RaycastAll(pos+Vector3.up*.7f,Vector3.down,1.2f,~0,QueryTriggerInteraction.Ignore).Where(h=>h.collider.transform.IsChildOf(root)&&h.normal.y>.8f).ToArray();if(down.Length==0)groundMissing.Add(new{tunnel=(string)t["id"],i,lane,pos=pos.ToString()});
   }checks.Add(new{id=(string)t["id"],samples=(n+1)*3,blocked=failures});
  }
  var mesh=root.GetComponentsInChildren<MeshFilter>();var domes=mesh.Where(m=>m.name.StartsWith("CF_B5_")&&m.name.Contains("Dome")).Select(m=>new{m.name,active=m.gameObject.activeInHierarchy,center=m.GetComponent<Renderer>().bounds.center.ToString(),size=m.GetComponent<Renderer>().bounds.size.ToString()}).ToArray();var tunnels=mesh.Where(m=>m.name.StartsWith("CF_B5-T")&&m.name.Contains("Vault")).Select(m=>new{m.name,active=m.gameObject.activeInHierarchy}).ToArray();
  var missingMesh=mesh.Where(m=>!m.sharedMesh).Select(m=>m.name).ToArray();var missingMats=root.GetComponentsInChildren<Renderer>().Where(r=>r.sharedMaterials.Any(m=>!m||!m.shader||m.shader.name=="Hidden/InternalErrorShader")).Select(r=>PathOf(r.transform)).ToArray();
  var result=new{scene=SceneManager.GetActiveScene().path,samples,checks,blocked,groundMissing,domes,tunnels,doors=root.Find("Pocket_Doors_Open").childCount,missingMesh,missingMats,player=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player")).transform.position.ToString()};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{samples,blocked=blocked.Count,missingGround=groundMissing.Count,domes=domes.Length,tunnels=tunnels.Length,result.doors,missingMesh,missingMats};
 }
 static void Shot(string name,Vector3 p,Vector3 target,bool aerial=false){var go=new GameObject("B5_ReviewCamera");var cam=go.AddComponent<Camera>();cam.transform.position=p;cam.transform.LookAt(target);cam.nearClipPlane=.04f;cam.farClipPlane=600;cam.fieldOfView=75;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.027f,.037f,.05f);cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;cam.allowMSAA=true;if(aerial){cam.orthographic=true;cam.orthographicSize=91;}
  var rt=new RenderTexture(1920,1200,24);rt.antiAliasing=4;var previous=RenderTexture.active;Texture2D tex=null;try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex=new Texture2D(1920,1200,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1920,1200),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=previous;cam.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Capture(){Init();var scene=SceneManager.GetActiveScene();var hidden=scene.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToDictionary(r=>r,r=>r.enabled);var changed=new Dictionary<MeshFilter,Mesh>();var temporary=new List<Mesh>();try{
  foreach(var r in hidden.Keys)r.enabled=false;
  Shot("C01_Entrance",new Vector3(-17.1f,-80.35f,-1.3f),new Vector3(-14.5f,-80.1f,-11.8f));
  Shot("C01_Experiment",new Vector3(-13.8f,-80.35f,-12.6f),new Vector3(-16.2f,-80.4f,-8.6f));
  Shot("C01_Observation",new Vector3(-9.2f,-80.35f,-10),new Vector3(-20.3f,-80.2f,-4.9f));
  Shot("C01_New_WestExit",new Vector3(-20.6f,-80.35f,-10.3f),new Vector3(-30,-80.35f,-13.2f));
  Shot("W01_Living",new Vector3(-88,-80.35f,38),new Vector3(-84.95f,-80.9f,32.72f));
  var t=floor["tunnels"].Single(t=>(string)t["id"]=="B5-T11");Vector3 pp=V(t["p"]),qq=V(t["q"]),dd=(qq-pp).normalized;Shot("T11_Corridor",pp+dd*7+Vector3.up*1.65f,pp+dd*20+Vector3.up*1.65f);
  // Temporary cutaway for evidence only; saved scene retains complete roofs.
  foreach(var mf in root.GetComponentsInChildren<MeshFilter>()){if(!(mf.name.Contains("Dome")||mf.name.Contains("Vault")||mf.name.Contains("CurvedLining")||mf.name.Contains("PortalCollars")||mf.name.Contains("ThreePortalRibs")))continue;var src=mf.sharedMesh;var copy=UnityEngine.Object.Instantiate(src);var vs=src.vertices;for(int sub=0;sub<src.subMeshCount;sub++){var tri=src.GetTriangles(sub);var kept=new List<int>();for(int i=0;i<tri.Length;i+=3)if(Enumerable.Range(0,3).All(k=>mf.transform.TransformPoint(vs[tri[i+k]]).y<-79.1f)){kept.Add(tri[i]);kept.Add(tri[i+1]);kept.Add(tri[i+2]);}copy.SetTriangles(kept,sub);}copy.RecalculateBounds();changed[mf]=src;mf.sharedMesh=copy;temporary.Add(copy);}
  Shot("B5_AllCaverns_Cutaway",new Vector3(0,130,-100),new Vector3(0,-82,0),true);
 }finally{foreach(var kv in changed)kv.Key.sharedMesh=kv.Value;foreach(var m in temporary)UnityEngine.Object.DestroyImmediate(m);foreach(var kv in hidden)kv.Key.enabled=kv.Value;EditorSceneManager.OpenScene(scene.path);}return new{images=7,sceneSavedRoofsIntact=true};}
}
